-- Scontro a squadre (SPEC §5.19, docs/COMBAT.md), stage 5, batch 2: the kits of the next 25 Delta
-- characters players own most after the first batch (src/lib/combat-kits-batch-2.ts on 24 November
-- 2026, described in docs/COMBAT-KITS.md). Each one was simulated on its own card: with its kit, in a
-- random team against a random team, it wins between 46% and 56%.
--
-- A kit an admin already saved from the EDITOR for one of these characters stays as it is.

insert into public.combat_kits (definition_id, kit)
select d.id, k.kit::jsonb
