join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P094', 'P016', 'P017', 'P021', 'P067', 'P106', 'P002', 'P082', 'P192', 'P063', 'P193', 'P196', 'P004', 'P020', 'P145', 'P147', 'P006', 'P011', 'P015', 'P023', 'P107', 'P124', 'P154', 'P195', 'P064')) <> 25 then
    raise exception 'a character of the second batch has no kit';
  end if;
end $$;
